/// Drive the full facade handshake against canned seed-0 fixtures.
///
/// Composes SH + SF into a `CannedTransport`, then calls
/// `DefaultStream::connect()` with `SeededRng::new(0)` and
/// `ClientParams::self_signed("tls-fixture.local")`. On return the captured
/// TX must equal CH || CF byte-for-byte; otherwise the handshake produced
/// different wire bytes than the Python reference and we return `Err(())`.
#[cfg(all(
    feature = "canned-replay",
    feature = "cipher-aes",
    not(feature = "chacha20"),
    not(feature = "rsa"),
    not(feature = "mlkem"),
    not(feature = "mldsa"),
))]
pub fn run_aes_ed25519_facade() -> Result<(), ()> {
    facade_scratch::with(run_aes_ed25519_facade_with_scratch)
}

/// Run the AES/Ed25519 facade with scratch stored in the current stack frame.
///
/// Hardware cycle measurement uses this form because the shared static-scratch
/// adapter protects its borrow by masking interrupts for the entire handshake.
/// A local scratch value needs no guard, allowing the SysTick overflow handler
/// to extend its counter while the operation runs.
#[cfg(all(
    feature = "canned-replay",
    feature = "cipher-aes",
    not(feature = "chacha20"),
    not(feature = "rsa"),
    not(feature = "mlkem"),
    not(feature = "mldsa"),
))]
pub fn run_aes_ed25519_facade_on_stack() -> Result<(), ()> {
    let mut scratch = krabitls::client::DefaultScratch::new();
    run_aes_ed25519_facade_with_scratch(&mut scratch)
}

// Same gate as its two callers: the AES/Ed25519 fixtures and
// `RuntimeSuitePolicy` it references are only compiled for that suite, so an
// ungated helper breaks the chacha / rsa / PQC footprint rows.
#[cfg(all(
    feature = "canned-replay",
    feature = "cipher-aes",
    not(feature = "chacha20"),
    not(feature = "rsa"),
    not(feature = "mlkem"),
    not(feature = "mldsa"),
))]
// `inline(never)`: a real caller boundary so a single `TlsStream` return slot is
// reused instead of the whole workload folding into the harness `main` (a ~5x
// stack multiplier that measures the rig, not the client).
#[inline(never)]
fn run_aes_ed25519_facade_with_scratch(
    scratch: &mut krabitls::client::DefaultScratch,
) -> Result<(), ()> {
    let mut rng = SeededRng::new(0);
    let transport =
        CannedTransport::<{ CLIENT_HELLO.len() + CLIENT_FINISHED.len() }>::new(&SERVER_STREAM);
    let params =
        ClientParams::self_signed("tls-fixture.local").suite_policy(RuntimeSuitePolicy::Default);

    let tls = DefaultStream::connect(&params, scratch, transport, &mut rng).map_err(|_| ())?;

    let captured = tls.transport().captured_tx();
    let expected_len = CLIENT_HELLO.len() + CLIENT_FINISHED.len();
    if captured.len() != expected_len
        || captured[..CLIENT_HELLO.len()] != CLIENT_HELLO[..]
        || captured[CLIENT_HELLO.len()..] != CLIENT_FINISHED[..]
    {
        return Err(());
    }
    Ok(())
}

/// Same facade as `run_aes_ed25519_facade`, but with a `Clocked` strategy so
/// the (always-compiled) cert validity-window check is exercised. `.text`
/// minus the `NoClock` build = the opt-in cost of validity.
#[cfg(all(
    feature = "canned-replay",
    feature = "cipher-aes",
    feature = "cert-der",
    not(feature = "chacha20"),
    not(feature = "rsa"),
    not(feature = "mlkem"),
    not(feature = "mldsa"),
))]
pub fn run_aes_ed25519_facade_clocked() -> Result<(), ()> {
    struct FixedT(u64);
    impl TimeSource for FixedT {
        fn now_unix_secs(&self) -> u64 {
            self.0
        }
    }

    type ClockedVerify = SafeStrategy<PinOrSelfSigned, DerCert, Clocked<FixedT>>;
    type ClockedStream<'s, T> =
        TlsStream<'s, T, DefaultConfig, ClockedVerify, 16384, 16645, 4096, 8>;

    facade_scratch::with(|scratch| {
        let mut rng = SeededRng::new(0);
        let transport = CannedTransport::<512>::new(&SERVER_STREAM);
        // 2026-06-24T12:00:00Z — inside the fixture cert's validity window.
        let strategy =
            SafeStrategy::with_clock(PinOrSelfSigned::self_signed(), Clocked(FixedT(1782302400)));
        let params = ClientParams::with_strategy("tls-fixture.local", strategy)
            .suite_policy(RuntimeSuitePolicy::Default);

        let tls = ClockedStream::connect(&params, scratch, transport, &mut rng).map_err(|_| ())?;

        let captured = tls.transport().captured_tx();
        let expected_len = CLIENT_HELLO.len() + CLIENT_FINISHED.len();
        if captured.len() != expected_len
            || captured[..CLIENT_HELLO.len()] != CLIENT_HELLO[..]
            || captured[CLIENT_HELLO.len()..] != CLIENT_FINISHED[..]
        {
            return Err(());
        }
        Ok(())
    })
}

