pub fn baseline_aes_ecdsa_chain() -> bool {
    black_box(&fx::CLIENT_HELLO);
    black_box(&fx::SERVER_HELLO);
    black_box(&fx::SERVER_FLIGHT);
    black_box(&fx::CLIENT_FINISHED);
    black_box(&fx::ROOT);
    true
}

