/// Links every server-cert verify width into one binary — a `.text` size probe
/// for the full monomorphization set. A single no-auth `connect()` statically
/// references the runtime
/// cert-verify dispatch, so with rsa+ecdsa+mldsa enabled every verify
/// monomorphization is linked — Ed25519 (CAP 16), RSA U1024 (CAP 32) + U2048
/// (CAP 64), ECDSA P-256 (CAP 8) + P-384 (CAP 12), ML-DSA. The empty transport
/// makes `connect` return `Err`; only the *linked* `.text` matters for the size
/// measurement, never run under QEMU.
#[cfg(all(
    feature = "full-stack",
    feature = "canned-replay",
    feature = "cipher-aes"
))]
pub fn run_full_stack() -> bool {
    facade_scratch::with(|scratch| {
        let mut rng = krabitls_fixtures::SeededRng::new(0);
        let transport = krabitls_fixtures::CannedTransport::<2048>::new(&[]);
        let params = krabitls::client::ClientParams::self_signed("x")
            .suite_policy(krabitls::client::RuntimeSuitePolicy::Default);
        // Empty transport → connect returns Err; the probe only needs the
        // symbols linked, so discard the result instead of reporting a failure.
        let _ = krabitls::client::DefaultStream::connect(&params, scratch, transport, &mut rng);
        true
    })
}

// secp256r1 (P-256) ECDHE + AES-128-GCM + ECDSA-P256 server cert — a fully
// coherent all-P-256 handshake (P-256 KEX *and* an ECDSA-P256 leaf). The seed-0
// capture offered X25519 + P-256 and the server selected P-256, so this needs
// `p256-kx` layered on the always-present `x25519-kx`. Server-auth only; there
// is no captured client second flight, so the check pins the ClientHello prefix
// (which proves the P-256 `key_share` was emitted) and that a Finished follows.
#[cfg(all(
    feature = "canned-replay",
    feature = "cipher-aes",
    feature = "p256-kx",
    feature = "ecdsa",
    not(feature = "chacha20"),
    not(feature = "rsa"),
    not(feature = "mlkem"),
    not(feature = "mldsa"),
))]
mod fixture_p256_ecdsa_facade {
    pub const CLIENT_HELLO: [u8; 224] = krabitls::hex_decode(include_str!(
        "../../../testdata/packets_p256_ecdsa/001_c2s_ClientHello.hex"
    ));
    pub const SERVER_HELLO: [u8; 128] = krabitls::hex_decode(include_str!(
        "../../../testdata/packets_p256_ecdsa/002_s2c_ServerHello.hex"
    ));
    pub const SERVER_FLIGHT: [u8; 653] = krabitls::hex_decode(include_str!(
        "../../../testdata/packets_p256_ecdsa/003_s2c_ServerFlight_encrypted.hex"
    ));
    pub const SERVER_STREAM: [u8; SERVER_HELLO.len() + SERVER_FLIGHT.len()] =
        concat_sh_sf!(SERVER_HELLO.len(), SERVER_FLIGHT.len());
    /// The Finished record framing is key-exchange-independent (5-byte record
    /// header + 4-byte handshake header + 32-byte SHA-256 verify_data + 1 inner
    /// content type + 16-byte GCM tag = 58), so the P-256 client Finished is the
    /// same 58 bytes as every other AES row — used to size the TX capture buffer
    /// and assert the exact captured length.
    pub const CLIENT_FINISHED_LEN: usize = 58;
}

